import gurobipy as gp
from gurobipy import GRB

def solve_greenweave(env):
    # Sets and parameters
    R = ['Organic Cotton', 'Jute', 'Linen']
    F = ['Organic Cotton Fabric', 'Jute Fabric', 'Linen Fabric']
    allowed_pairs = {
        'Organic Cotton Fabric': ['Organic Cotton', 'Jute'],
        'Jute Fabric': ['Jute', 'Linen'],
        'Linen Fabric': ['Organic Cotton', 'Jute', 'Linen']
    }
    C_purch = {'Organic Cotton': 350, 'Jute': 400, 'Linen': 300}
    C_proc = {'Organic Cotton': 100, 'Jute': 80, 'Linen': 150}
    Availability = {'Organic Cotton': 1000, 'Jute': 800, 'Linen': 600}
    Efficiency = {'Organic Cotton Fabric': 0.7, 'Jute Fabric': 0.75, 'Linen Fabric': 0.8}
    Required = {'Organic Cotton Fabric': 300, 'Jute Fabric': 400, 'Linen Fabric': 200}

    # Create model
    model = gp.Model(env=env)
    model.ModelName = "GreenWeave"

    # Decision variables
    x = {}
    for f in F:
        for r in allowed_pairs[f]:
            x[(r, f)] = model.addVar(name=f"x_{r}_{f}", lb=0)
    model.update()

    # Objective function
    obj = gp.quicksum((C_purch[r] + C_proc[r]) * x[(r, f)] for f in F for r in allowed_pairs[f])
    model.setObjective(obj, GRB.MINIMIZE)

    # Fabric production requirements
    for f in F:
        lhs = gp.quicksum(Efficiency[f] * x[(r, f)] for r in allowed_pairs[f])
        model.addConstr(lhs >= Required[f], name=f"Fabric_{f}_Requirement")

    # Raw material availability
    for r in R:
        allowed_fabrics = [f for f in F if r in allowed_pairs[f]]
        lhs = gp.quicksum(x[(r, f)] for f in allowed_fabrics)
        model.addConstr(lhs <= Availability[r], name=f"RawMaterial_{r}_Availability")

    # Optimize
    model.optimize()

    # Output
    if model.status == GRB.OPTIMAL:
        print(f"FINAL_OBJECTIVE={model.objVal}")
