inventory = {
    1: {'standard': 150, 'premium': 30},
    2: {'standard': 250, 'premium': 100},
    3: {'standard': 300, 'premium': 70}
}

distance = {
    1: {1: 0, 2: 12, 3: 18},
    2: {1: 12, 2: 0, 3: 15},
    3: {1: 18, 2: 15, 3: 0}
}

required_p = {
    'premium': 200/3,
    'standard': 700/3
}

