model = gp.Model("transportation")

# Decision variables
y = model.addVars(C, H, P, name="y", lb=0)

# Objective function
model.setObjective(gp.quicksum(distance[c][h] * y[c, h, p] for c in C for h in H for p in P), GRB.MINIMIZE)

# Inventory capacity constraints
for c in C:
    for p in P:
        model.addConstr(gp.quicksum(y[c, h, p] for h in H) <= inventory[c][p], name=f"inventory_{c}_{p}")

# Hub demand constraints
for h in H:
    for p in P:
        model.addConstr(gp.quicksum(y[c, h, p] for c in C) == required_p[p], name=f"hub_demand_{h}_{p}")

# Optimize
model.optimize()

# Output
if model.status == GRB.OPTIMAL:
    print(f"FINAL_OBJECTIVE={model.objVal}")
