import gurobipy as gp
from gurobipy import GRB

def solve(env):
    model = gp.Model(env=env)
    DC = [1, 2]
    GT = [1, 2, 3]
    FixedCost = {1: 1000, 2: 2000}
    Wage = {1: 500, 2: 900}
    ProcessRate = {
        1: {1: 20, 2: 25},
        2: {1: 18, 2: 22},
        3: {1: 15, 2: 20}
    }
    Demand = {1: 120, 2: 150, 3: 200}
    MaxCoordinators = {1: 7, 2: 7}

    Activate = model.addVars(DC, vtype=GRB.BINARY, name="Activate")
    Coordinators = model.addVars(DC, lb=0, ub=MaxCoordinators, vtype=GRB.INTEGER, name="Coordinators")

    for g in GT:
        model.addConstr(gp.quicksum(ProcessRate[g][d] * Coordinators[d] for d in DC) >= Demand[g], name=f"Shipment_{g}")

    for d in DC:
        model.addConstr(Coordinators[d] <= MaxCoordinators[d] * Activate[d], name=f"Capacity_{d}")

    model.setObjective(gp.quicksum(FixedCost[d] * Activate[d] + Wage[d] * Coordinators[d] for d in DC), GRB.MINIMIZE)

    model.optimize()

    if model.status == GRB.OPTIMAL:
        print(f"FINAL_OBJECTIVE={model.objVal}")
