import gurobipy as gp
from gurobipy import GRB

def solve_chemco(env):
    # Sets
    R = ['Alpha', 'Beta', 'Gamma', 'Delta', 'Epsilon']
    S = ['Standard', 'Premium']

    # Parameters
    Avail_r = {'Alpha': 12000, 'Beta': 10500, 'Gamma': 8000, 'Delta': 5000, 'Epsilon': GRB.INFINITY}
    Cost_r = {'Alpha': 15.0, 'Beta': 12.0, 'Gamma': 10.0, 'Delta': 18.0, 'Epsilon': 16.0}
    VI_r = {'Alpha': 95, 'Beta': 88, 'Gamma': 82, 'Delta': 105, 'Epsilon': 100}
    FlashPoint_r = {'Alpha': 45, 'Beta': 55, 'Gamma': 60, 'Delta': 40, 'Epsilon': 50}
    BoilingPoint_r = {'Alpha': 150, 'Beta': 180, 'Gamma': 200, 'Delta': 130, 'Epsilon': 160}
    Density_r = {'Alpha': 0.85, 'Beta': 0.92, 'Gamma': 0.89, 'Delta': 0.87, 'Epsilon': 0.91}
    Demand_s = {'Standard': 8500, 'Premium': 25000}
    Price_s = {'Standard': 25.50, 'Premium': 28.75}
    VI_min_s = {'Standard': 85, 'Premium': 92}
    FlashPoint_exact_s = {'Standard': 50, 'Premium': 50}
    BoilingPoint_min_s = {'Standard': 140, 'Premium': 140}
    Density_exact_s = {'Standard': 0.88, 'Premium': 0.88}

    # Create model
    m = gp.Model(env=env)

    # Variables
    x = m.addVars(R, S, name="x", lb=0)

    # Objective: Maximize profit
    revenue = gp.quicksum(Price_s[s] * gp.quicksum(x[r, s] for r in R) for s in S)
    cost = gp.quicksum(Cost_r[r] * gp.quicksum(x[r, s] for s in S) for r in R)
    m.setObjective(revenue - cost, GRB.MAXIMIZE)

    # Constraints
    # 1. Demand satisfaction
    for s in S:
        m.addConstr(gp.quicksum(x[r, s] for r in R) >= Demand_s[s], name=f"Demand_{s}")

    # 2. Property requirements
    for s in S:
        # Viscosity Index (VI)
        lhs_vi = gp.quicksum(x[r, s] * VI_r[r] for r in R)
        rhs_vi = VI_min_s[s] * gp.quicksum(x[r, s] for r in R)
        m.addConstr(lhs_vi >= rhs_vi, name=f"VI_{s}")

        # Flash Point
        lhs_flash = gp.quicksum(x[r, s] * FlashPoint_r[r] for r in R)
        rhs_flash = FlashPoint_exact_s[s] * gp.quicksum(x[r, s] for r in R)
        m.addConstr(lhs_flash == rhs_flash, name=f"FlashPoint_{s}")

        # Boiling Point
        lhs_boil = gp.quicksum(x[r, s] * BoilingPoint_r[r] for r in R)
        rhs_boil = BoilingPoint_min_s[s] * gp.quicksum(x[r, s] for r in R)
        m.addConstr(lhs_boil >= rhs_boil, name=f"BoilingPoint_{s}")

        # Density
        lhs_density = gp.quicksum(x[r, s] * Density_r[r] for r in R)
        rhs_density = Density_exact_s[s] * gp.quicksum(x[r, s] for r in R)
        m.addConstr(lhs_density == rhs_density, name=f"Density_{s}")

    # 3. Beta content restriction
    for s in S:
        m.addConstr(x['Beta', s] <= 0.35 * gp.quicksum(x[r, s] for r in R), name=f"Beta_Content_{s}")

    # 4. Availability limits
    for r in R:
        if r != 'Epsilon':
            m.addConstr(gp.quicksum(x[r, s] for s in S) <= Avail_r[r], name=f"Availability_{r}")

    # Optimize
    m.optimize()

    # Output
    if m.status == GRB.OPTIMAL:
        print(f"FINAL_OBJECTIVE={m.objVal}")
