from gurobipy import GRB

model = gp.Model(env=env)

# Define sets
R = ['Organic Cotton', 'Jute', 'Linen']
F = ['Organic Cotton Fabric', 'Jute Fabric', 'Linen Fabric']

# Parameters
p = {'Organic Cotton': 350, 'Jute': 400, 'Linen': 300}
c = {'Organic Cotton': 100, 'Jute': 80, 'Linen': 150}
A = {'Organic Cotton': 1000, 'Jute': 800, 'Linen': 600}
r = {'Organic Cotton Fabric': 300, 'Jute Fabric': 400, 'Linen Fabric': 200}
e = {'Organic Cotton Fabric': 0.7, 'Jute Fabric': 0.75, 'Linen Fabric': 0.8}

# Variables
x = {}
for rm in R:
    for f in F:
        x[(rm, f)] = model.addVar(lb=0, vtype=GRB.CONTINUOUS, name=f"x_{rm}_{f}")

# Objective
model.setObjective(gp.quicksum((p[rm] + c[rm]) * x[(rm, f)] for rm in R for f in F), GRB.MINIMIZE)

# Output requirements constraints
for f in F:
    model.addConstr(gp.quicksum(e[f] * x[(rm, f)] for rm in R) >= r[f], name=f"output_{f}")

# Availability constraints
for rm in R:
    model.addConstr(gp.quicksum(x[(rm, f)] for f in F) <= A[rm], name=f"availability_{rm}")

model.optimize()

if model.Status == GRB.OPTIMAL:
    print(f"FINAL_OBJECTIVE={model.ObjVal:.17g}")
