from gurobipy import GRB

model = gp.Model(env=env)

# Raw materials and solvents
R = ['Alpha', 'Beta', 'Gamma', 'Delta', 'Epsilon']
S = ['Standard', 'Premium']

# Parameters
availability = {'Alpha': 12000, 'Beta': 10500, 'Gamma': 8000, 'Delta': 5000, 'Epsilon': float('inf')}
cost_r = {'Alpha': 15.0, 'Beta': 12.0, 'Gamma': 10.0, 'Delta': 18.0, 'Epsilon': 16.0}
vi = {'Alpha': 95, 'Beta': 88, 'Gamma': 82, 'Delta': 105, 'Epsilon': 100}
flash_point = {'Alpha': 45, 'Beta': 55, 'Gamma': 60, 'Delta': 40, 'Epsilon': 50}
boiling_point = {'Alpha': 150, 'Beta': 180, 'Gamma': 200, 'Delta': 130, 'Epsilon': 160}
density = {'Alpha': 0.85, 'Beta': 0.92, 'Gamma': 0.89, 'Delta': 0.87, 'Epsilon': 0.91}
demand = {'Standard': 8.5, 'Premium': 25}
price = {'Standard': 25.50, 'Premium': 28.75}
vi_min = {'Standard': 85, 'Premium': 92}
flash_point_exact = {'Standard': 50, 'Premium': 50}
boiling_point_min = {'Standard': 140, 'Premium': 140}
density_exact = {'Standard': 0.88, 'Premium': 0.88}

# Decision variables
x = model.addVars(R, S, name="x")

# Objective: maximize profit
revenue = gp.quicksum(price[s] * gp.quicksum(x[r, s] for r in R) for s in S)
cost = gp.quicksum(cost_r[r] * gp.quicksum(x[r, s] for s in S) for r in R)
model.setObjective(revenue - cost, GRB.MAXIMIZE)

# Constraints
for s in S:
    # Demand constraint
    model.addConstr(gp.quicksum(x[r, s] for r in R) >= 1000 * demand[s], name=f"demand_{s}")
    # Flash point exact
    model.addConstr(gp.quicksum(x[r, s] * flash_point[r] for r in R) == flash_point_exact[s] * gp.quicksum(x[r, s] for r in R), name=f"flash_{s}")
    # Density exact
    model.addConstr(gp.quicksum(x[r, s] * density[r] for r in R) == density_exact[s] * gp.quicksum(x[r, s] for r in R), name=f"density_{s}")
    # Viscosity index minimum
    model.addConstr(gp.quicksum(x[r, s] * vi[r] for r in R) >= vi_min[s] * gp.quicksum(x[r, s] for r in R), name=f"vi_min_{s}")
    # Boiling point minimum
    model.addConstr(gp.quicksum(x[r, s] * boiling_point[r] for r in R) >= boiling_point_min[s] * gp.quicksum(x[r, s] for r in R), name=f"boiling_min_{s}")
    # Beta limit
    model.addConstr(x['Beta', s] <= 0.35 * gp.quicksum(x[r, s] for r in R), name=f"beta_limit_{s}")

# Availability constraints for raw materials (excluding Epsilon)
for r in R:
    if r != 'Epsilon':
        model.addConstr(gp.quicksum(x[r, s] for s in S) <= availability[r], name=f"availability_{r}")

model.optimize()

if model.Status == GRB.OPTIMAL:
    print(f"FINAL_OBJECTIVE={model.ObjVal:.17g}")
