    ('N3', 'N5', 100, 3),
    ('N4', 'S1', 1e9, 1),
    ('N4', 'S2', 1e9, 2),
    ('N5', 'S2', 1e9, 1),
    ('N5', 'S3', 1e9, 2),
]

