    'S1': {'Cola': 30, 'Juice': 15, 'Water': 10},
    'S2': {'Cola': 20, 'Juice': 25, 'Water': 15},
    'S3': {'Cola': 10, 'Juice': 5, 'Water': 20},
}

# Define production capacities
production_capacities = {
    'P1': {'Cola': 40, 'Juice': 30, 'Water': 20},
    'P2': {'Cola': 30, 'Juice': 25, 'Water': 40},
}

# Create variables
