drinks = ['Cola', 'Juice', 'Water']
for d in drinks:
    variables[d] = {}
    for arc in arcs:
        i, j, cap, cost = arc
        var_name = f"x_{d}_{i}_{j}"
        variables[d][(i, j)] = model.addVar(lb=0, name=var_name)

# Add capacity constraints for each arc
for arc in arcs:
    i, j, cap, cost = arc
    expr = gp.LinExpr()
    for d in drinks:
        expr.addTerm(1, variables[d][(i, j)])
    model.addConstr(expr <= cap, name=f"capacity_{i}_{j}")

# Add production capacity constraints
for P in ['P1', 'P2']:
    for d in drinks:
        expr = gp.LinExpr()
        for arc in arcs:
            if arc[0] == P:
                expr.addTerm(1, variables[d][(arc[0], arc[1])])
        model.addConstr(expr <= production_capacities[P][d], name=f"production_{P}_{d}")

# Add demand constraints
for S in ['S1', 'S2', 'S3']:
    for d in drinks:
        expr = gp.LinExpr()
        for arc in arcs:
            if arc[1] == S:
                expr.addTerm(1, variables[d][(arc[0], arc[1])])
        model.addConstr(expr >= demands[S][d], name=f"demand_{S}_{d}")

