import gurobipy as gp
from gurobipy import GRB

# Data from the problem
customers = {
    1: {"x": 3, "y": 5, "service_time": 5, "time_window": (9.5, 10.0)},
    2: {"x": 5, "y": 8, "service_time": 8, "time_window": (10.0, 10.3333)},
    3: {"x": 2, "y": 1, "service_time": 5, "time_window": (9.0, 9.3333)},
    4: {"x": 8, "y": 6, "service_time": 10, "time_window": (10.5, 11.0)},
    5: {"x": 4, "y": 2, "service_time": 6, "time_window": (9.75, 10.25)},
    6: {"x": 9, "y": 8, "service_time": 7, "time_window": (11.25, 11.6667)},
    7: {"x": 1, "y": 9, "service_time": 9, "time_window": (10.1667, 10.6667)},
    8: {"x": 1, "y": 3, "service_time": 5, "time_window": (9.25, 9.6667)},
    9: {"x": 6, "y": 4, "service_time": 12, "time_window": (10.3333, 10.8333)},
    10: {"x": 7, "y": 1, "service_time": 6, "time_window": (11.0, 11.3333)},
}
depot = {"x": 0, "y": 0}

# Precompute distances and travel times
num_nodes = 11  # 0 (depot) to 10 (customers)
positions = {0: (0, 0)}
for i in range(1, 11):
    positions[i] = (customers[i]["x"], customers[i]["y"])

distance = {}
travel_time = {}
for i in range(11):
    for j in range(11):
        dx = positions[i][0] - positions[j][0]
        dy = positions[i][1] - positions[j][1]
        distance[(i, j)] = (dx**2 + dy**2)**0.5
        travel_time[(i, j)] = distance[(i, j)] / 30  # 30 km/h

# Time window centers
time_window_centers = {}
for i in range(1, 11):
    e, l = customers[i]["time_window"]
    time_window_centers[i] = (e + l) / 2

# Create model
model = gp.Model(env=env)

# Decision variables
x = {}
for i in range(11):
    for j in range(11):
        if i != j:
            x[(i, j)] = model.addVar(vtype=GRB.BINARY, name=f"x_{i}_{j}")
a = {}
for i in range(1, 11):
    a[i] = model.addVar(lb=0, name=f"a_{i}")

# Objective function
obj = 0
for i in range(11):
    for j in range(11):
        if i != j:
            obj += 5 * distance[(i, j)] * x[(i, j)]
for i in range(1, 11):
    obj += 0.2 * (a[i] - time_window_centers[i])**2
model.setObjective(obj, GRB.MINIMIZE)

# Constraints
# Flow conservation
for i in range(1, 11):
    model.addConstr(gp.quicksum(x[(j, i)] for j in range(11) if j != i) == 1, name=f"enter_{i}")
    model.addConstr(gp.quicksum(x[(i, j)] for j in range(11) if j != i) == 1, name=f"exit_{i}")

# Depot constraints
model.addConstr(gp.quicksum(x[(0, j)] for j in range(1, 11)) == 1, name="depot_exit")
model.addConstr(gp.quicksum(x[(i, 0)] for i in range(1, 11)) == 1, name="depot_enter")

# Time constraints
M = 1e6
for i in range(11):
    for j in range(11):
        if i != j:
            model.addConstr(a[j] >= a[i] + customers[i]["service_time"]/60 + travel_time[(i, j)] - M * (1 - x[(i, j)]), name=f"time_lower_{i}_{j}")
            model.addConstr(a[j] <= a[i] + customers[i]["service_time"]/60 + travel_time[(i, j)] + M * (1 - x[(i, j)]), name=f"time_upper_{i}_{j}")

# Initial departure from depot
for j in range(1, 11):
    model.addConstr(a[j] >= 8.5 + travel_time[(0, j)] - M * (1 - x[(0, j)]), name=f"depot_departure_lower_{j}")
    model.addConstr(a[j] <= 8.5 + travel_time[(0, j)] + M * (1 - x[(0, j)]), name=f"depot_departure_upper_{j}")

model.optimize()

if model.Status == GRB.OPTIMAL:
    print(f"FINAL_OBJECTIVE={model.ObjVal:.17g}")
